-- 0182: aṣl from every book, batch 04 — each book's own statement (read by its profile; Lane in English), verbatim
-- with block + page and a plain English line; primary = the meaning most books share. Quotes checked against blocks.
-- aslmb_04: aṣl per book for 25 roots that rested on Ibn Fāris alone (AGR:VOC:002/017).
-- Each row: the book's own words as printed + block + page + entry. ONE primary per root, by the reading most books share
-- (tie -> the earliest book). Standalone: INSERT OR IGNORE + guarded UPDATEs; safe to re-run. No row deleted.
-- ثعب
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ثعب:khalil_kitab_ayn', 'ثعب', '5cff4abe8ad8d4b079ca53edad', 'ثَعَبْتُ الماء أَثْعَبُهُ ثَعْباً، أي فجّرته فانثعب', 'I let the water burst out, and it flowed', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_e61492e2297dd277', '466', NULL, 'blk_kay_a9538e0225372de9', 0, NULL, 'Marker: head gloss. Reading: making water flow. Primary: flowing out — 9 of 10 books (al-Khalīl blk_kay_a9538e0225372de9; Ibn Durayd blk_jam_e19434ed6ec4e3b6; al-Jawharī blk_sih_8a9bae2059bcf0b1; Ibn Fāris blk_mqy_8f2ce03a9f91918b; al-Rāghib blk_mfr_1cc69fe7c76883db; Lisān blk_lsn_9328898b18b9ed17; al-Qāmūs blk_qms_4bd39fb7fbd5f3b1; Tāj blk_taj_99ae3b1fbf40ef8e; Lane blk_lane_478568fa27c761fa). Other readings: big snake: al-Miṣbāḥ.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ثعب:ibn_durayd_jamharat_lugha', 'ثعب', '5cff4abe8ad8d4b079ca53edad', 'والثعب: انثعاب المَاء. وَمَاء مثعب وأثعوب إِذا سَالَ.', 'water pouring out and running', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_01b035d0a851cace', '223', NULL, 'blk_jam_e19434ed6ec4e3b6', 0, NULL, 'Marker: first gloss of this root. Reading: water flowing.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ثعب:jawhari_sihah', 'ثعب', '5cff4abe8ad8d4b079ca53edad', 'ثعبت الماء ثعبا: فجرته', 'I let the water burst out', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_fd786522f3eb5604', '168', 1, 'blk_sih_8a9bae2059bcf0b1', 0, NULL, 'Marker: head gloss. Reading: making water flow.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ثعب:raghib_mufradat', 'ثعب', '5cff4abe8ad8d4b079ca53edad', 'ثَعَبْتُ الماء فَانْثَعَبَ، أي: فجّرته وأسلته فسال', 'I opened the water and let it run', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_a233ec383431563e', '173', 1, 'blk_mfr_1cc69fe7c76883db', 0, NULL, 'Marker: opening definition (why the snake is so named). Reading: making water flow.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ثعب:ibn_manzur_lisan_arab', 'ثعب', '5cff4abe8ad8d4b079ca53edad', 'ثَعَبَ الماءَ والدَّمَ ونحوَهما يَثْعَبهُ ثَعْباً: فَجَّره', 'made water or blood burst out', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_e577cdd84e5e054d', '236', 1, 'blk_lsn_9328898b18b9ed17', 0, NULL, 'Marker: head gloss. Reading: making flow.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ثعب:fayyumi_misbah_munir', 'ثعب', '5cff4abe8ad8d4b079ca53edad', 'الثُّعْبَانُ الْحَيَّةُ الْعَظِيمَةُ', 'a huge snake', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_2d565aa78ba2e07f', '433', NULL, 'blk_msb_55f7b90efa479f48', 0, NULL, 'Marker: head gloss (a noun only). Reading: big snake. Differs from the main reading (flowing out).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:ثعب:qamus_muhit', 'ثعب', '5cff4abe8ad8d4b079ca53edad', 'ثَعَبَ الماءَ والدَّم كمنع: فَجَرَهُ فَانْثَعَبَ', 'made water or blood burst out, so it flowed', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_3ecf485240f8e1dc', NULL, NULL, 'blk_qms_4bd39fb7fbd5f3b1', 0, NULL, 'Marker: Qāmūs gloss. Reading: making flow.', 'high', 'active');
