INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:جرع:zabidi_taj_arus', 'جرع', '3b9e70aea0d52bbc70fd4baf2e', 'الجَرْعَةُ، بالفَتْحِ، ويُحَرَّكُ: الرَّمْلَةُ العَذَاةُ الطَّيِّبَةُ المُنْبِتِ، الَّتِي لَا وُعُوثَةَ فيهَا', 'good, firm sandy ground where plants grow', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_1eb559f6d766a09e', '429', 20, 'blk_taj_77686ac03d907a28', 0, NULL, 'Marker: Qāmūs gloss. Reading: sandy ground. Differs from the main reading (gulping).', 'high', 'active');
