INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:جور:fayyumi_misbah_munir', 'جور', 'c919a32939cef9e5a97becb195', 'جَارَ فِي حُكْمِهِ يَجُورُ جَوْرًا ظَلَمَ', 'he judged unjustly', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_af62570e30edbc3f', '576', NULL, 'blk_msb_cb61ba402d14724b', 0, NULL, 'Marker: head gloss. Reading: injustice. Differs from the main reading (turning off the road).', 'high', 'active');
