INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:جور:lane_lexicon', 'جور', 'c919a32939cef9e5a97becb195', 'He declined, or deviated, from the right course', 'he turned off the right way', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_d60fb86c1692e7a9', '483', NULL, 'blk_lane_a186b7cf4a8265c6', 0, NULL, 'Marker: first sense A1. Reading: turning off the way.', 'high', 'active');
UPDATE ar_ling_root_asl SET note_md = trim(CASE WHEN instr(coalesce(note_md,''),'Primary:') > 0 THEN substr(note_md, 1, instr(note_md,'Primary:') - 1) ELSE coalesce(note_md,'') END) || ' ' || 'Reading: turning off the road.', updated_at = datetime('now') WHERE id = 'ASL:جور:maqayis_lugha' AND coalesce(note_md,'') NOT LIKE '%Reading:%';
UPDATE ar_ling_root_asl SET is_primary = CASE WHEN id = 'ASL:جور:ibn_durayd_jamharat_lugha' THEN 1 ELSE 0 END, updated_at = datetime('now') WHERE root_norm = 'جور' AND EXISTS (SELECT 1 FROM ar_ling_root_asl WHERE id = 'ASL:جور:ibn_durayd_jamharat_lugha' AND status <> 'rejected');
-- جوس
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:جوس:jawhari_sihah', 'جوس', 'fbaf21fa3d8c203318a72639f6', 'جاسوا خلال الديار، أي تخلّلوها فطلبوا ما فيها', 'they went through the homes, searching them', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_ae02af1fdfb6b58a', '1811', 3, 'blk_sih_80341fe92d0c38f0', 0, NULL, 'Marker: «أي». Reading: going through. Primary: going through — 3 of 6 books (al-Jawharī blk_sih_80341fe92d0c38f0; Ibn Fāris blk_mqy_fdce21132c13130e; Lisān blk_lsn_3e16f16140f5a8e5). Other readings: searching thoroughly: al-Qāmūs, Tāj, Lane.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:جوس:ibn_manzur_lisan_arab', 'جوس', 'fbaf21fa3d8c203318a72639f6', 'الجَوْسُ: مَصْدَرُ جاسَ جَوْساً وجَوَساناً، تَرَدَّدَ', 'going to and fro', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_3cee91a929599043', '3056', 6, 'blk_lsn_3e16f16140f5a8e5', 0, NULL, 'Marker: head gloss. Reading: going to and fro.', 'high', 'active');
