INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:جوس:lane_lexicon', 'جوس', 'fbaf21fa3d8c203318a72639f6', 'He sought for, or after, (Zj, Ṣ, A, Ḳ,) a thing, (Zj, A, Ḳ,) or news, or tidings, (Ṣ,) with the utmost of his endeavour.', 'he searched for something with all his effort', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_ce049b3f3e2e1394', '484', NULL, 'blk_lane_ae17f31820ef8321', 0, NULL, 'Marker: first sense A1. Reading: searching hard. Differs from the main reading (going through).', 'high', 'active');
